# Stories for albums 801–850 (long format agreed with the owner: three paragraphs + a listening tip,
# ~220–230 words per story (min ~210), three picks with ~12-word notes). Original Hebrew; facts checked on the web, uncertain ones softened.
# Used by tools/batches/build_801_850.py; later edits: python3 tools/apply_stories.py stories_801_850
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(801, [
'''פאלפ היא להקה משפילד שבצפון אנגליה, שג׳רוויס קוקר הקים כשהיה עוד נער בבית הספר, בסוף שנות השבעים. במשך יותר מעשר שנים היא כמעט לא הצליחה: הופעות קטנות, תקליטים שאיש לא קנה, הרכב שהתחלף שוב ושוב. רק באמצע שנות התשעים, כשגל הבריטפופ הציף את אנגליה, הגיעה סוף סוף ההצלחה. Different Class יצא בסתיו 1995, הגיע למקום הראשון במצעד הבריטי וזכה בפרס מרקורי, וקוקר, גבוה, רזה, במשקפיים ובחליפה מיושנת, הפך לאחד האנשים המדוברים במדינה.''',
'''השירים הם סיפורים קטנים וחדים על החיים הבריטיים: על מעמדות, על מין, על מסיבות ועל השכונה. Common People מספר על סטודנטית עשירה שרוצה "לחיות כמו האנשים הפשוטים", וקוקר עונה לה בזעם הולך וגובר שהיא לעולם לא תבין מה זה באמת. Disco 2000 הוא שיר פופ קופצני על חברת ילדות בשם דבורה, ועל פגישה שקבעו פעם ליד המזרקה בשנת אלפיים. Something Changed הוא שיר אהבה עדין על המקריות שבה אנשים נפגשים. הקול של קוקר עובר מלחישה מפתה לצעקה, והמילים שלו מצחיקות, עצובות ומדויקות.''',
'''Different Class נחשב לאחד מאלבומי הבריטפופ הטובים ביותר, לצד Parklife של בלר (אלבום 771) ו־Definitely Maybe של אואזיס (אלבום 767). מה שמייחד אותו הוא נקודת המבט: לא הכוכב המנצח, אלא הבחור הצנום מהצד, שמסתכל על כולם ורואה הכל. Common People הפך להמנון של דור שלם, וקוקר נשאר דמות אהובה באנגליה.''',
'''הקשיבו ל־Common People עד הסוף, ושימו לב איך השיר מאיץ ומתגבר בהדרגה, עד שהוא כמעט מתפוצץ. אחר כך שמעו את Bar Italia, השיר האחרון, על בוקר עייף אחרי לילה ארוך בלונדון.''',
], [
('Common People', 'סיפור חד ומצחיק על סטודנטית עשירה, שהולך ומתגבר עד פיצוץ אדיר.'),
('Disco 2000', 'פופ קופצני על חברת ילדות ופגישה שנקבעה פעם ליד המזרקה.'),
('Something Changed', 'שיר אהבה עדין ומתוק על המקריות שבה שני אנשים נפגשים.'),
])

add(802, [
'''לפטפילד הם שני מוזיקאים מלונדון, ניל ברנס ופול דיילי, שהתחילו לעבוד יחד בסוף שנות השמונים, בימים שבהם מוזיקת הדאנס האלקטרונית כבשה את בריטניה. הם הוציאו כמה סינגלים שהפכו לאהובים במועדונים, וב־1995 הגיע אלבום הבכורה שלהם, Leftism. הוא היה מועמד לפרס מרקורי, נמכר היטב, ונחשב עד היום לאחד האלבומים שהראו שמוזיקה אלקטרונית יכולה להיות אלבום שלם להאזנה בבית, ולא רק ערב בריקודים.''',
'''הצליל מחבר בין האוס, טכנו ודאב, הסגנון הג׳מייקני שבו הבס עמוק והצלילים מהדהדים. יש כאן קצבים ארוכים ומתפתחים, בס שמרגישים בגוף, וזמרים אורחים מעולמות שונים. Release the Pressure פותח עם הזמר הג׳מייקני ארל סיקסטין, ומשלב רגאיי עם קצב אלקטרוני. Open Up הוא שיתוף פעולה מפתיע עם ג׳ון ליידון, הזמר של הסקס פיסטולס, שצועק מעל קצב מהיר וסוחף. Original, עם הזמרת טוני הלידיי, איטי וחלומי יותר, ו־Song of Life הוא מסע ארוך ויפה שנבנה לאט.''',
'''Leftism הפך לאחד מאבני היסוד של מה שנקרא אז "דאנס לאלבומים", לצד אורביטל (אלבומים 750 ו־780) והכימיקל בראדרס (אלבום 792). לפטפילד היו ידועים גם בהופעות רועשות במיוחד, עם מערכת הגברה עוצמתית מאוד. כמה מהקטעים שלהם הופיעו בסרטים ובפרסומות, והאלבום נשמע רענן גם היום. ברנס ודיילי עבדו עליו לאט ובקפידה, במשך כמה שנים, וזה מורגש: כל קטע בנוי בסבלנות, שכבה אחרי שכבה, וכמעט שום דבר בו לא נשמע מקרי או חפוז.''',
'''זה אלבום שכדאי לשמוע בווליום גבוה, ברמקולים טובים או באוזניות, כדי להרגיש את הבס. התחילו ב־Release the Pressure, ותנו לו לבנות את עצמו לאט.''',
], [
('Release the Pressure', 'פתיחה שמחברת רגאיי וקצב אלקטרוני, עם קול חם ובס עמוק.'),
('Open Up', 'ג׳ון ליידון צועק מעל קצב מהיר וסוחף, שיתוף פעולה מפתיע וחשמלי.'),
('Song of Life', 'מסע אלקטרוני ארוך ויפה, שנבנה לאט ומתרומם בהדרגה.'),
])

add(803, [
'''דיאנג׳לו, מייקל ארצ׳ר, גדל בריצ׳מונד שבווירג׳יניה, בנו של כומר, ולמד לנגן על פסנתר ועל עוגב בכנסייה כבר כילד קטן. כנער הוא זכה בתחרות הכישרונות המפורסמת של תיאטרון אפולו בהארלם, ובגיל עשרים ואחת יצא אלבום הבכורה שלו, Brown Sugar, ב־1995. בזמן שמוזיקת הנשמה של אותן שנים הייתה מלאה בקצבים חדים ובהפקות נוצצות, דיאנג׳לו הלך לכיוון אחר לגמרי: חם, איטי ומלא נשמה ישנה.''',
'''דיאנג׳לו ניגן בעצמו על רוב הכלים, ובעיקר על פסנתר חשמלי ועל עוגב, שנותנים לאלבום צליל עגול ורך. הקצבים מושפעים מהיפ הופ, אבל השירה והמלודיות שואבות מהסול של שנות השבעים, ממרווין גיי, מאל גרין ומפרינס. השיר שנותן לאלבום את שמו, Brown Sugar, הוא גרוב איטי וממכר, עם קול שמתפתל ומתלחש. Lady הוא שיר אהבה מתוק עם פזמון שנדבק מיד, ו־Cruisin׳ הוא גרסה מלטפת לשיר הידוע של סמוקי רובינסון. האלבום כולו נשמע כמו לילה ארוך ושקט.''',
'''Brown Sugar נחשב לאחד האלבומים שפתחו את מה שנקרא "ניאו סול", גל של זמרים צעירים שחזרו לצליל החם והאורגני של הסול הקלאסי. מקסוול (אלבום 823) ואריקה באדו הגיעו מיד אחריו. דיאנג׳לו עצמו הוציא מעט מאוד אלבומים, עם הפסקות ארוכות של שנים ביניהם, אבל כל אחד מהם נחשב לאירוע. גם היום, זמרים צעירים רבים מזכירים את Brown Sugar כאלבום שלימד אותם איך סול יכול להישמע חם, אישי ומודרני בבת אחת.''',
'''השוו בין Brown Sugar לבין What's Going On של מרווין גיי (אלבום 207), ושמעו כמה דיאנג׳לו למד ממנו, בקול הכפול ובקצב הרגוע.''',
], [
('Brown Sugar', 'גרוב איטי וממכר, עם עוגב חם וקול שמתפתל ומתלחש.'),
('Lady', 'שיר אהבה מתוק עם פזמון שנדבק כבר בהאזנה הראשונה.'),
("Cruisin'", 'גרסה מלטפת ורכה לשיר הידוע של סמוקי רובינסון, עם כלי מיתר.'),
])

add(804, [
'''כשאואזיס ממנצ׳סטר הוציאו את (What's the Story) Morning Glory? באוקטובר 1995, הם כבר היו להקה מצליחה, אחרי Definitely Maybe (אלבום 767). אבל האלבום השני הפך אותם לתופעה. כמה חודשים לפני כן התנהל "הקרב" המפורסם מול בלר, כשהשתי הלהקות הוציאו סינגל באותו יום, והעיתונים הפכו את זה לסיפור לאומי. בלר ניצחו בקרב על הסינגל, אבל אואזיס ניצחו במלחמה: האלבום נמכר במיליוני עותקים והפך לאחד הנמכרים בתולדות בריטניה.''',
'''את השירים כתב נואל גלאגר, האח המבוגר, והזמר הוא ליאם, האח הצעיר, עם קול מחוספס ויהיר. הצליל גדול ורחב: גיטרות עבות, מלודיות פשוטות שמזמינות לשיר יחד, והשפעה גלויה מהביטלס. Wonderwall, עם הגיטרה האקוסטית והצ׳לו, הפך לאחד השירים המוכרים בעולם. Don't Look Back in Anger, שבו שר נואל עצמו, הוא בלדה עם פסנתר שנפתחת לפזמון אדיר. Champagne Supernova, השיר האחרון, נמשך יותר משבע דקות, עם פול ולר כאורח בגיטרה.''',
'''באוגוסט 1996 הופיעו אואזיס פעמיים בנבוורת׳, מול כמאתיים וחמישים אלף איש בשני ערבים, אחת ההופעות הגדולות בתולדות בריטניה. זה היה שיא הבריטפופ. מאז, הלהקה התפרקה וחזרה, אבל השירים מהאלבום הזה נשארו מושרים בכל פאב ובכל מגרש כדורגל. המבקרים לא תמיד אהבו את האלבום כשיצא, וחלקם מצאו אותו פשוט מדי, אבל הקהל החליט אחרת, ועם השנים גם רבים מהמבקרים שינו את דעתם.''',
'''השוו את האלבום ל־Different Class של פאלפ (אלבום 801), שיצא באותו חודש: שני צדדים שונים מאוד של אותה תקופה. ושימו לב לפזמון של Don't Look Back in Anger.''',
], [
('Wonderwall', 'גיטרה אקוסטית וצ׳לו, ואחד השירים המוכרים בעולם מאז שנות התשעים.'),
("Don't Look Back in Anger", 'נואל שר בלדה עם פסנתר, שנפתחת לפזמון שכל קהל שר יחד.'),
('Champagne Supernova', 'סיום ארוך וחולמני של שבע דקות, עם פול ולר בגיטרה.'),
])

add(805, [
'''גולדי, קליפורד פרייס, גדל בוולברהמפטון שבאנגליה, ובשנות השמונים התפרסם בכלל כאמן גרפיטי, עם שיני זהב שהפכו לסימן ההיכר שלו. בתחילת שנות התשעים הוא התאהב בג׳אנגל, המוזיקה האלקטרונית המהירה שצמחה במועדונים של לונדון, עם קצבי תופים שבורים ומהירים ובס עמוק ואיטי. הוא הקים חברת תקליטים בשם מטלהדז, וב־1995 הוציא את Timeless, אחד האלבומים הראשונים של הסגנון, שנקרא אחר כך דראם אנד בייס, שהגיע לקהל רחב.''',
'''הקטע שפותח את האלבום ונותן לו את שמו, Timeless, נמשך יותר מעשרים דקות, ובנוי כמו יצירה בכמה חלקים. בתוכו מסתתר Inner City Life, שיר יפה במיוחד עם קולה של הזמרת דיאן שרלמן, שמרחף מעל תופים מהירים ומתוחים. גולדי שילב כלי מיתר, פסנתר ג׳אז ואווירה של סול, כך שהמוזיקה נשמעת גם מהירה וגם רכה, גם עירונית וגם חולמנית. Angel ו־State of Mind ממשיכים באותה רוח, עם שירה ומלודיות שמרככות את הקצב.''',
'''Timeless הראה שג׳אנגל הוא לא רק מוזיקה למועדונים, אלא משהו שאפשר להקשיב לו בבית כמו לאלבום ג׳אז או סול. הוא נכנס לעשירייה הראשונה במצעד הבריטי, וגולדי הפך לכוכב, ואחר כך גם לשחקן ולדמות טלוויזיה מוכרת באנגליה. דרכו, הרבה אנשים שמעולם לא נכנסו למועדון ג׳אנגל גילו את הסגנון, ואמנים רבים, מפופ ועד ג׳אז, התחילו לשאול ממנו קצבים ורעיונות.''',
'''הקשיבו לקטע הפתיחה הארוך מתחילתו ועד סופו, באוזניות, ושימו לב איך מעל התופים המהירים נשאר כל הזמן משהו איטי ונינוח, הבס והקול.''',
], [
('Timeless', 'יצירה של עשרים דקות, עם תופים מהירים, כלי מיתר וקול נשי מרחף.'),
('State of Mind', 'קטע רך ומלודי, שמראה כמה ג׳אנגל יכול להיות עדין.'),
('Angel', 'שירה חמה מעל קצב שבור ומהיר, אווירה של לילה בעיר.'),
])

add(806, [
'''אלאניס מוריסט נולדה באוטווה שבקנדה, ועוד כנערה הייתה כוכבת פופ קטנה בארצה, עם שני אלבומים של פופ ריקודים קליל. בגיל עשרים בערך היא עברה ללוס אנג׳לס, התחילה לכתוב עם המפיק גלן באלארד, ובתוך זמן קצר נולדו שירים אישיים, כועסים וכנים בהרבה. Jagged Little Pill יצא ב־1995 בחברת התקליטים של מדונה, ולאט לאט הפך לאחת התופעות הגדולות של העשור. הוא נמכר בעשרות מיליוני עותקים בכל העולם, וזכה בפרס הגראמי לאלבום השנה.''',
'''הצליל הוא רוק אלטרנטיבי נגיש, עם גיטרות, תופים חזקים ומלודיות שנכנסות מיד לראש, אבל מה שבולט הוא הקול של מוריסט: היא שרה, צועקת, צוחקת ומתלוננת, כמו מישהי שכותבת ביומן ולא אכפת לה מי ישמע. You Oughta Know, עם פלי מהרד הוט צ׳ילי פפרס בבס, הוא מכתב זועם לאקס שעזב. Hand in My Pocket הוא שיר קליל ואופטימי על הסתירות שבכל אחד מאיתנו. Ironic, עם הפזמון המפורסם, הפך לאחד השירים המוכרים של שנות התשעים, ואנשים מתווכחים עד היום אם הדוגמאות שבו באמת אירוניות.''',
'''Jagged Little Pill פתח את הדלת לגל שלם של זמרות־כותבות שכתבו בגלוי על כעס, על מין ועל בלבול, בלי לייפות דבר. הוא נשמע כמו קול של צעירה אמיתית ולא של כוכבת מעוצבת, ובגלל זה כל כך הרבה בנות ובנים הזדהו איתו. ב־2018 עלה בברודווי מחזמר שלם שנבנה על השירים מהאלבום.''',
'''השוו את מוריסט לטורי איימוס (אלבום 726) ולפיונה אפל (אלבום 818): שלוש זמרות שכתבו באותן שנים על אותם נושאים, כל אחת בדרך אחרת לגמרי. ושימו לב לשיר הנסתר בסוף האלבום, אם הוא מופיע.''',
], [
('You Oughta Know', 'מכתב זועם וחשוף לאקס, עם בס סוער וצעקה שלא מתנצלת.'),
('Hand in My Pocket', 'שיר קליל ואופטימי על הסתירות הקטנות שבכל אחד מאיתנו.'),
('Ironic', 'פזמון מפורסם ודוגמאות שאנשים מתווכחים עליהן עד היום.'),
])

add(807, [
'''סקרימינג טריז הגיעו מאלנסבורג, עיירה קטנה במדינת וושינגטון, הרחק מסיאטל. הלהקה התחילה באמצע שנות השמונים, סביב שני אחים גדולים וגבוהים, גארי לי ואן קונר, והזמר מארק לנגן, בעל אחד הקולות העמוקים והמחוספסים ברוק. הם היו חלק מסצנת הגראנג׳ עוד לפני שהיה לה שם, אבל אף פעם לא הצליחו כמו נירוונה או סאונדגרדן. Dust, שיצא ב־1996, היה האלבום האחרון שלהם, ורבים חושבים שהוא גם הטוב ביותר.''',
'''הצליל של Dust רחב וחם יותר מהגראנג׳ הרגיל: יש בו גיטרות כבדות, אבל גם עוגב, גיטרות אקוסטיות, צלילים מזרחיים קלים והשפעה ברורה מהרוק הפסיכדלי של שנות השישים. הקול של לנגן נשמע כמו של אדם שכבר ראה הכל, עייף וחכם, והמילים עוסקות באובדן, בחטא ובגאולה. Halo of Ashes פותח בעוצמה, עם מלודיה מתפתלת. All I Know הוא שיר רוק עם פזמון שנכנס לראש. Dying Days, עם הגיטריסט מייק מקקרדי מפרל ג׳ם, הוא שיר אפל ויפה, ו־Gospel Plow, השיר האחרון, מבוסס על שיר גוספל ישן.''',
'''Dust לא הצליח להפוך את הלהקה לכוכבת, ואחרי כמה שנים היא התפרקה. אבל מארק לנגן המשיך לקריירת סולו ארוכה ומוערכת, שיתף פעולה עם קווינס אוף דה סטון אייג׳ ועם אמנים רבים, והפך לאחד הקולות האהובים של הרוק האלטרנטיבי, עד מותו ב־2022.''',
'''אם אהבתם את Superunknown של סאונדגרדן (אלבום 768) או את Dirt של אליס אין צ׳יינס (אלבום 729), זה הצד החם והאיטי יותר של אותה סצנה. שמעו את הקול של לנגן באוזניות, בשקט.''',
], [
('Halo of Ashes', 'פתיחה עוצמתית עם מלודיה מתפתלת וגוון מזרחי עדין.'),
('All I Know', 'שיר רוק חזק עם פזמון שנכנס לראש וקול עמוק ומחוספס.'),
('Dying Days', 'שיר אפל ויפה, עם סולו גיטרה של מייק מקקרדי מפרל ג׳ם.'),
])

add(808, [
'''סופר פרי אנימלס היא להקה מקארדיף שבוויילס, שהתחילה לשיר בוולשית, השפה המקומית, ורק אחר כך עברה לאנגלית. הזמר, גרף ריס, כותב שירים מוזרים, מצחיקים ומלאי דמיון, והלהקה כולה נשמעה כמו חבורה של חברים שנהנים להשתולל באולפן. היא חתמה בחברת התקליטים קריישן, אותה חברה שבה הקליטו אואזיס ופריימל סקרים, ו־Fuzzy Logic, אלבום הבכורה, יצא ב־1996. על העטיפה יש תמונות של הווארד מרקס, מבריח סמים וולשי מפורסם, בכל התחפושות שבהן השתמש כדי להתחמק מהמשטרה.''',
'''המוזיקה היא פופ פסיכדלי, שמחבר בין גיטרות של בריטפופ, הרמוניות בסגנון הביץ׳ בויז והביטלס, וקצת שגעון אלקטרוני. כל שיר נשמע אחר, וכמעט בכל אחד יש רעיון מפתיע. Something 4 the Weekend הוא שיר פופ שמח וקליל על תוכניות לסוף השבוע. Hometown Unicorn, השיר הראשון שהוציאו באנגלית, מספר על חד קרן שהלך לאיבוד, עם מלודיה מתוקה ועצובה. If You Don't Want Me to Destroy You הוא שיר שקט ויפה, ו־God! Show Me Magic פותח את האלבום במהירות ובאנרגיה של פאנק.''',
'''הלהקה הייתה ידועה גם בשטויות שלה: היא קנתה טנק צבאי ישן, צבעה אותו בכחול והביאה אותו לפסטיבלים. אבל מאחורי ההומור עמדה להקה רצינית מאוד, שהוציאה סדרה ארוכה של אלבומים מצוינים, כולל אלבום שלם בוולשית, ונחשבה לאחת הלהקות המקוריות של בריטניה בשנות התשעים.''',
'''אם אהבתם את I Should Coco של סופרגראס (אלבום 795), שתי הלהקות חולקות את אותה שמחה צעירה. התחילו ב־Something 4 the Weekend, ואחר כך תנו לשאר האלבום להפתיע.''',
], [
('Something 4 the Weekend', 'פופ שמח וקליל על תוכניות לסוף השבוע, עם פזמון מתוק.'),
('Hometown Unicorn', 'שיר מתוק ועצוב על חד קרן שהלך לאיבוד, עם הרמוניות יפות.'),
('If You Don\'t Want Me to Destroy You', 'שיר שקט ויפה, עם מלודיה עדינה ואווירה חולמנית.'),
])

add(809, [
'''פטבוי סלים הוא נורמן קוק מברייטון, שכבר היה מוזיקאי מצליח עוד לפני השם הזה: בשנות השמונים ניגן בס בלהקת הפופ ההאוסמרטינס, ואחר כך הצליח עם פרויקטים של מוזיקת ריקודים. באמצע שנות התשעים הוא התחיל לתקלט במועדון קטן בברייטון, ותחת השם פטבוי סלים הוציא ב־1996 את Better Living Through Chemistry, אלבום הבכורה שלו, בחברת התקליטים הקטנה סקינט. הוא היה אחד האלבומים הראשונים של סגנון שנקרא "ביג ביט".''',
'''ביג ביט הוא מוזיקה אלקטרונית שמחה ורועשת, שמחברת בין קצבים של היפ הופ, גיטרות של רוק, דגימות מתקליטים ישנים ובס כבד. פטבוי סלים הוא אמן של דגימות: הוא לוקח קטע קצר מתקליט נשכח, חוזר עליו שוב ושוב, ובונה ממנו מסיבה. Everybody Needs a 303 מוקדש למכשיר הבס הקטן של רולנד, שהפך לצליל המרכזי של מוזיקת האסיד. Going Out of My Head משתמש בריף גיטרה ידוע מהשישים, ו־Santa Cruz הוא קטע מסחרר שבונה את עצמו לאט. הכל נשמע כמו ערב שמח במועדון, בלי שום יומרה.''',
'''האלבום הזה היה רק ההתחלה: שנתיים אחר כך הוציא פטבוי סלים את You've Come a Long Way, Baby, עם Praise You ו־Right Here, Right Now, והפך לאחד התקליטנים המפורסמים בעולם. אבל כאן אפשר לשמוע את הנוסחה שלו בפעם הראשונה, צעירה, מבולגנת ומלאת הומור.''',
'''השוו את האלבום ל־Exit Planet Dust של הכימיקל בראדרס (אלבום 792), שעשו אז מוזיקה דומה. שמעו את Everybody Needs a 303, ושימו לב לצליל הבס המפעפע שחוזר שוב ושוב.''',
], [
('Everybody Needs a 303', 'מחווה שמחה לצליל הבס המפעפע של מוזיקת האסיד.'),
('Going Out of My Head', 'ריף גיטרה מהשישים הופך כאן למסיבה רועשת ומטורפת.'),
('Santa Cruz', 'קטע מסחרר שבונה את עצמו לאט, עד שאי אפשר לשבת.'),
])

add(810, [
'''קול קית׳, קית׳ תורנטון, הוא ראפר מהברונקס שבניו יורק, שהתפרסם כבר בשנות השמונים עם הלהקה אולטרמגנטיק MCs. הוא תמיד היה מוזר, מקורי ובלתי צפוי, ובאמצע שנות התשעים המציא דמות חדשה: דוקטור אוקטגון, רופא נשים ומנתח מטורף, חייזר שמטייל בזמן ומגיע מכוכב צדק. Dr. Octagonecologyst יצא ב־1996 בחברה קטנה, הפך לשמועה בין אוהבי היפ הופ, ושנה אחר כך הוצא מחדש בחברה גדולה, והגיע לקהל רחב בהרבה.''',
'''את המוזיקה הפיק דן דה אוטומייטור, מפיק מסן פרנסיסקו, שבנה עולם מוזיקלי מפחיד ויפה: כלי מיתר, פסנתר, צלילים חלליים וקצבים איטיים ומאיימים, כמו פסקול לסרט מדע בדיוני זול. התקליטן קיו־ברט, מגדולי האמנים של הפטיפון, מוסיף שריטות מבריקות. המילים של קול קית׳ הן זרם של מילים רפואיות, דימויים מוזרים, הומור גס ושטויות מבריקות, ולפעמים הן בוטות מאוד. Blue Flowers, עם כינור מרחף ומבשר רעות, הוא הקטע המפורסם. Earth People מצחיק ומוזר, ו־3000 נשמע כמו טיסה בחלל.''',
'''Dr. Octagonecologyst הפך לאחד האלבומים החשובים של ההיפ הופ העצמאי, והראה שאפשר לעשות ראפ ניסיוני, מצחיק ואפל, בלי לחשוב על המצעדים. דן דה אוטומייטור המשיך לעבוד עם גורילז ועם פרויקטים רבים, וקול קית׳ המשיך להמציא דמויות חדשות עוד שנים רבות.''',
'''אם תמשיכו ל־Endtroducing של די ג׳יי שאדו (אלבום 815), תשמעו עוד אלבום מאותו עולם: שאדו הקליט אותו בעזרת ציוד שהשאיל לו דן דה אוטומייטור. התחילו ב־Blue Flowers.''',
], [
('Blue Flowers', 'כינור מרחף ומבשר רעות, ראפ מוזר וקצב איטי ומאיים.'),
('Earth People', 'מצחיק ומוזר, ההכרזה של הרופא החייזר לתושבי כדור הארץ.'),
('3000', 'קצב חללי וצלילים מרחפים, כמו טיסה בספינת חלל ישנה.'),
])
